<?php
declare(strict_types=1);
function db():PDO{static $pdo;if(!$pdo)$pdo=new PDO('mysql:host='.DB_HOST.';port='.DB_PORT.';dbname='.DB_NAME.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);return $pdo;}
function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function url(string $p=''):string{return rtrim(BASE_URL,'/').($p===''?'/':'/'.ltrim($p,'/'));}
function go(string $p):void{header('Location: '.url($p));exit;}
function csrf():string{if(empty($_SESSION['_csrf']))$_SESSION['_csrf']=bin2hex(random_bytes(32));return '<input type="hidden" name="_csrf" value="'.e($_SESSION['_csrf']).'">';}
function check_csrf():void{if(!isset($_SESSION['_csrf'],$_POST['_csrf'])||!hash_equals($_SESSION['_csrf'],(string)$_POST['_csrf'])){http_response_code(400);exit('Your session token expired. Reload the page and try again.');}}
function flash(?string $m=null,string $k='ok'):?array{if($m!==null){$_SESSION['_flash']=[$m,$k];return null;}$f=$_SESSION['_flash']??null;unset($_SESSION['_flash']);return $f;}
function audit(?int $uid,string $action,string $table,?int $target,string $description,string $result='success'):void{$s=db()->prepare('INSERT INTO audit_logs (user_id,action,target_table,target_id,description,ip_address,result) VALUES (?,?,?,?,?,?,?)');$s->execute([$uid,$action,$table,$target,substr($description,0,255),$_SERVER['REMOTE_ADDR']??null,$result]);}
function owned_account(PDO $pdo,int $customerId,int $accountId):bool{$s=$pdo->prepare('SELECT 1 FROM account_holders WHERE customer_id=? AND account_id=?');$s->execute([$customerId,$accountId]);return (bool)$s->fetchColumn();}
function notify_account_application(PDO $pdo,int $customerId,int $accountId,?int $secondCustomerId=null):void{$s=$pdo->prepare('SELECT user_id FROM users WHERE linked_customer_id=? AND status=\'active\'');$check=$pdo->prepare("SELECT 1 FROM notifications WHERE user_id=? AND type='account_request' AND message LIKE ? LIMIT 1");$i=$pdo->prepare('INSERT INTO notifications (user_id,type,message) VALUES (?,\'account_request\',?)');foreach(array_filter(array_unique([$customerId,$secondCustomerId])) as $customer){$s->execute([(int)$customer]);$userId=$s->fetchColumn();if($userId){$check->execute([(int)$userId,'%application #'.$accountId.'%']);if(!$check->fetchColumn())$i->execute([(int)$userId,'Account application #'.$accountId.' received and pending staff review.']);}}}
function unread_notification_count(int $userId):int{try{$s=db()->prepare('SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0');$s->execute([$userId]);return (int)$s->fetchColumn();}catch(Throwable $x){return 0;}}
function sync_approval_messages(PDO $pdo,int $customerId,int $userId):void{
    $s=$pdo->prepare('SELECT kyc_status FROM customers WHERE customer_id=?');$s->execute([$customerId]);$kyc=$s->fetchColumn();if($kyc&&$kyc!=='pending'){$message='Your KYC status is '.ucfirst((string)$kyc).'.';$q=$pdo->prepare("SELECT 1 FROM notifications WHERE user_id=? AND type='kyc_update' AND message=? LIMIT 1");$q->execute([$userId,$message]);if(!$q->fetchColumn()){$i=$pdo->prepare("INSERT INTO notifications (user_id,type,message) VALUES (?,'kyc_update',?)");$i->execute([$userId,$message]);}}
    $requests=$pdo->prepare("SELECT type,message FROM notifications WHERE user_id=? AND type IN ('account_request','loan_request') ORDER BY notification_id");$requests->execute([$userId]);
    foreach($requests->fetchAll() as $request){if(!preg_match('/application #(\d+)/i',(string)$request['message'],$match))continue;$applicationId=(int)$match[1];if($applicationId<1)continue;$decisionType=null;$message='';
        if($request['type']==='account_request'){$q=$pdo->prepare('SELECT a.status,c.kyc_status FROM accounts a JOIN account_holders h ON h.account_id=a.account_id JOIN customers c ON c.customer_id=h.customer_id WHERE a.account_id=? AND h.customer_id=?');$q->execute([$applicationId,$customerId]);$row=$q->fetch();if($row&&$row['status']==='active'){$decisionType='account_approved';$message='Your account application #'.$applicationId.' has been approved and activated.';}elseif($row&&$row['kyc_status']==='rejected'){$decisionType='account_rejected';$message='Your account application #'.$applicationId.' needs further review. Please contact your branch.';}}
        else{$q=$pdo->prepare('SELECT l.status,l.loan_type FROM loans l JOIN loan_parties p ON p.loan_id=l.loan_id WHERE l.loan_id=? AND p.customer_id=? AND p.party_role=\'borrower\'');$q->execute([$applicationId,$customerId]);$row=$q->fetch();if($row&&in_array($row['status'],['approved','active','closed'],true)){$decisionType='loan_approved';$message='Your '.$row['loan_type'].' application #'.$applicationId.' was approved.';}elseif($row&&$row['status']==='rejected'){$decisionType='loan_rejected';$message='Your loan application #'.$applicationId.' was not approved.';}}
        if($decisionType){$q=$pdo->prepare('SELECT 1 FROM notifications WHERE user_id=? AND type=? AND message LIKE ? LIMIT 1');$q->execute([$userId,$decisionType,'%application #'.$applicationId.'%']);if(!$q->fetchColumn()){$i=$pdo->prepare('INSERT INTO notifications (user_id,type,message) VALUES (?,?,?)');$i->execute([$userId,$decisionType,$message]);}}
    }
}
function notify_transfer_parties(PDO $pdo,int $senderId,int $debitTransactionId,?int $creditTransactionId,float $amount,string $reference):void{
    try{$source=$pdo->prepare('SELECT account_title,account_number FROM accounts WHERE account_id=(SELECT account_id FROM transactions WHERE transaction_id=?)');$source->execute([$debitTransactionId]);$from=$source->fetch();if(!$from)return;$sent=substr('Money sent BDT '.number_format($amount,2).' from account ending '.substr($from['account_number'],-4).'. Reference '.$reference.'.',0,255);$add=$pdo->prepare('INSERT INTO notifications (user_id,type,message) VALUES (?,\'transfer_sent\',?)');$add->execute([$senderId,$sent]);if($creditTransactionId===null)return;$target=$pdo->prepare('SELECT a.account_id,a.account_title,a.account_number FROM transactions t JOIN accounts a ON a.account_id=t.account_id WHERE t.transaction_id=?');$target->execute([$creditTransactionId]);$to=$target->fetch();if(!$to)return;$receivers=$pdo->prepare("SELECT DISTINCT u.user_id FROM account_holders h JOIN users u ON u.linked_customer_id=h.customer_id JOIN user_roles ur ON ur.user_id=u.user_id JOIN roles r ON r.role_id=ur.role_id WHERE h.account_id=? AND u.status='active' AND r.role_name='Customer'");$receivers->execute([(int)$to['account_id']]);$message=substr('Money received BDT '.number_format($amount,2).' into account ending '.substr($to['account_number'],-4).'. Reference '.$reference.'.',0,255);$notice=$pdo->prepare('INSERT INTO notifications (user_id,type,message) VALUES (?,\'transfer_received\',?)');foreach($receivers->fetchAll(PDO::FETCH_COLUMN) as $receiverId)$notice->execute([(int)$receiverId,$message]);}catch(Throwable $x){}
}
function render_start(string $title):void{
    $u=current_user();if($u){try{sync_approval_messages(db(),(int)$u['customer_id'],(int)$u['id']);}catch(Throwable $x){}}$f=flash();$unread=$u?unread_notification_count((int)$u['id']):0;
    ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> · BankEase</title><link rel="stylesheet" href="<?=e(url('assets/css/site.css'))?>"><link rel="stylesheet" href="<?=e(url('assets/css/customer.css'))?>"><link rel="stylesheet" href="<?=e(url('assets/css/money-movement.css'))?>"><link rel="stylesheet" href="<?=e(url('assets/css/applications.css'))?>"><link rel="stylesheet" href="<?=e(url('assets/css/cards-notifications.css'))?>"><script defer src="<?=e(url('assets/js/site.js'))?>"></script></head><body><a class="skip" href="#main">Skip to content</a><header class="top"><a class="brand" href="<?=e(url())?>"><b>B</b> BankEase</a><button class="menu" type="button" aria-expanded="false" aria-controls="nav">Menu</button><nav id="nav" aria-label="Main navigation"><a href="<?=e(url('rates.php'))?>">Rates</a><a href="<?=e(url('branches.php'))?>">Branches</a><?php if($u):?><a href="<?=e(url('dashboard.php'))?>">Dashboard</a><a href="<?=e(url('accounts.php'))?>">My accounts</a><a href="<?=e(url('activity.php'))?>">Activity</a><a href="<?=e(url('transfer.php'))?>">Transfer</a><a href="<?=e(url('beneficiaries.php'))?>">Beneficiaries</a><a href="<?=e(url('loans.php'))?>">Loans</a><a href="<?=e(url('cards.php'))?>">Cards</a><a href="<?=e(url('notifications.php'))?>">Notifications<?php if($unread):?> <span class="nav-badge"><?=$unread?></span><?php endif;?></a><a class="nav-cta" href="<?=e(url('logout.php'))?>">Log out</a><?php else:?><a href="<?=e(url('login.php'))?>">Log in</a><a class="nav-cta" href="<?=e(url('register.php'))?>">Open account</a><?php endif;?></nav></header><main id="main" class="wrap"><?php if($f):?><div class="notice <?=e($f[1])?>" role="status"><?=e($f[0])?></div><?php endif;?><?php
}
function render_end():void{?></main><footer class="footer"><strong>BankEase</strong><span>Everyday banking, made clear.</span><span>Academic banking system demonstration · <?=date('Y')?></span></footer></body></html><?php }
